def is_balanced(text):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set('([{')
    closing = set(')]}')
    for ch in text:
        if ch in opening:
            stack.append(ch)
        elif ch in closing:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return len(stack) == 0
